3	use std::fs::File;
4	use std::path::Path;
5	use std::process::ExitCode;
6	
7	const USAGE: &str = "Usage: inkseal --version\n       inkseal digest <file>\n       inkseal check-digest <file> <digest>";
8	
9	fn main() -> ExitCode {
10	    // 使用 args_os 而非 args：命令行参数是操作系统给出的原始字节，
11	    // 在允许非 UTF-8 文件名的系统上这类路径是合法路径，必须原样保留。
12	    let mut args = env::args_os().skip(1);
13	    match args.next() {
14	        Some(ref cmd) if cmd.as_encoded_bytes() == b"--version" && args.next().is_none() => {
15	            println!("inkseal 0.1.0");
16	            ExitCode::SUCCESS
17	        }
18	        Some(ref cmd) if cmd.as_encoded_bytes() == b"digest" => {
19	            let (Some(path), None) = (args.next(), args.next()) else {
20	                eprintln!("{USAGE}");
21	                return ExitCode::from(2);
22	            };
23	            run_digest(Path::new(&path))
24	        }
25	        Some(ref cmd) if cmd.as_encoded_bytes() == b"check-digest" => {
26	            let (Some(path), Some(expected), None) = (args.next(), args.next(), args.next()) else {
27	                eprintln!("inkseal: check-digest requires exactly two arguments: <file> <digest>");
28	                eprintln!("{USAGE}");
29	                return ExitCode::from(2);
30	            };
31	            run_check_digest(Path::new(&path), &expected)
32	        }
33	        _ => {
34	            // 未知子命令（即便含有非 UTF-8 字节）等用法错误统一走这里。
35	            eprintln!("{USAGE}");
36	            ExitCode::from(2)
37	        }
38	    }
39	}
40	
41	fn run_digest(path: &Path) -> ExitCode {
42	    // 仅在输出错误信息时做损失性转换；打开文件始终使用原始路径，
43	    // 绝不把用于显示的文字当作实际路径访问。
44	    let display = path_display(path);
45	    let file = match File::open(path) {
46	        Ok(file) => file,
47	        Err(err) => {
48	            eprintln!("inkseal: cannot open '{display}': {err}");
49	            return ExitCode::FAILURE;
50	        }
51	    };
52	    match inkseal::digest_reader(file) {
53	        Ok(digest) => {
54	            println!("{}", digest.to_hex());
55	            ExitCode::SUCCESS
56	        }
57	        Err(err) => {
58	            eprintln!("inkseal: cannot read '{display}': {err}");
59	            ExitCode::FAILURE
60	        }
61	    }
62	}
63	
64	/// 解析用户给出的预期摘要：必须恰好是 64 个 ASCII 十六进制字符（大小写
65	/// 均可），按其表示的 32 字节摘要值比较。不做任何空白裁剪——前缀、空格、
66	/// 末尾换行、长度不对或含非十六进制字符都视为格式错误。参数无法解码为
67	/// 合法文字同样视为格式错误。
68	fn parse_expected_digest(arg: &OsStr) -> Result<[u8; 32], String> {
69	    let bytes = arg.as_encoded_bytes();
70	    if bytes.len() != 64 {
71	        return Err(format!(
72	            "expected digest must be exactly 64 ASCII hexadecimal characters, got {}",
73	            bytes.len()
74	        ));
75	    }
76	    let mut out = [0u8; 32];
77	    for (i, pair) in bytes.chunks(2).enumerate() {
78	        let hi = hex_nibble(pair[0])
79	            .ok_or_else(|| "expected digest contains a non-hexadecimal character".to_string())?;
80	        let lo = hex_nibble(pair[1])
81	            .ok_or_else(|| "expected digest contains a non-hexadecimal character".to_string())?;
82	        out[i] = (hi << 4) | lo;
83	    }
84	    Ok(out)
85	}
