87	fn hex_nibble(b: u8) -> Option<u8> {
88	    match b {
89	        b'0'..=b'9' => Some(b - b'0'),
90	        b'a'..=b'f' => Some(b - b'a' + 10),
91	        b'A'..=b'F' => Some(b - b'A' + 10),
92	        _ => None,
93	    }
94	}
