96	fn run_check_digest(path: &Path, expected_arg: &OsStr) -> ExitCode {
97	    // 先校验摘要格式；格式不合法时绝不打开文件——即使路径本身也不存在，
98	    // 仍报告摘要格式问题。
99	    let expected = match parse_expected_digest(expected_arg) {
100	        Ok(bytes) => bytes,
101	        Err(reason) => {
102	            eprintln!("inkseal: invalid expected digest: {reason}");
103	            eprintln!("{USAGE}");
104	            return ExitCode::from(2);
105	        }
106	    };
107	
108	    // 仅在输出错误信息时做损失性转换；打开文件始终使用原始路径，
109	    // 绝不把用于显示的文字当作实际路径访问。
110	    let display = path_display(path);
111	    let file = match File::open(path) {
112	        Ok(file) => file,
113	        Err(err) => {
114	            eprintln!("inkseal: cannot open '{display}': {err}");
115	            return ExitCode::FAILURE;
116	        }
117	    };
118	    let actual = match inkseal::digest_reader(file) {
119	        Ok(digest) => digest,
120	        Err(err) => {
121	            eprintln!("inkseal: cannot read '{display}': {err}");
122	            return ExitCode::FAILURE;
123	        }
124	    };
125	
126	    if actual.as_bytes() == &expected {
127	        println!("OK");
128	        ExitCode::SUCCESS
129	    } else {
130	        // 内容不匹配：预期与实际都以 64 个小写十六进制字符呈现。
131	        let mut expected_hex = String::with_capacity(64);
