1	//! `inkseal digest <文件>` 的端到端回归测试：以真实子进程运行编译出的命令，
2	//! 在临时目录中创建真实文件，验证命令确实按用户给出的路径访问文件，
3	//! 且输出、退出码、错误提示遵循 README 约定的行为。
4	//!
5	//! 重点保障：用户传入的真实路径（操作系统原始字节）与错误提示中显示的
6	//! 路径文字（损失性转换、控制字符转义）之间的区别——显示文本绝不参与
7	//! 文件访问，路径文字也不参与摘要计算。
8	
9	use std::ffi::{OsStr, OsString};
10	use std::fs;
11	use std::path::{Path, PathBuf};
12	use std::process::{Command, Output};
13	
14	/// 待测试的命令行程序（Cargo 为集成测试提供编译好的二进制路径）。
15	fn inkseal() -> Command {
16	    Command::new(env!("CARGO_BIN_EXE_inkseal"))
17	}
18	
19	fn run_digest(path: &OsStr) -> Output {
20	    inkseal()
21	        .arg("digest")
22	        .arg(path)
23	        .output()
24	        .expect("failed to run inkseal")
25	}
26	
27	fn run_args(args: &[&OsStr]) -> Output {
28	    inkseal()
29	        .args(args)
30	        .output()
31	        .expect("failed to run inkseal")
32	}
33	
34	/// 每个测试独立的临时目录，退出作用域时清理。
35	struct TestDir(PathBuf);
36	
37	impl TestDir {
38	    fn new(name: &str) -> Self {
39	        let dir = std::env::temp_dir().join(format!(
40	            "inkseal-cli-test-{}-{name}",
41	            std::process::id()
42	        ));
43	        let _ = fs::remove_dir_all(&dir);
44	        fs::create_dir_all(&dir).expect("create temp dir");
45	        TestDir(dir)
46	    }
47	
48	    fn path(&self) -> &Path {
49	        &self.0
50	    }
51	
52	    /// 在目录下创建指定名字（可以是任意 OsStr，包括非 UTF-8 字节）的文件。
53	    fn write_file(&self, name: &OsStr, contents: &[u8]) -> PathBuf {
54	        let path = self.0.join(name);
55	        fs::write(&path, contents).expect("write test file");
56	        path
57	    }
58	}
59	
60	impl Drop for TestDir {
61	    fn drop(&mut self) {
62	        let _ = fs::remove_dir_all(&self.0);
63	    }
64	}
65	
66	/// 成功摘要的标准输出形态：恰好 64 个小写十六进制字符加一个末尾换行。
67	fn assert_hex_stdout(stdout: &[u8]) -> &str {
68	    let text = std::str::from_utf8(stdout).expect("stdout must be UTF-8 hex");
69	    assert!(
70	        text.ends_with('\n'),
71	        "stdout must end with a newline: {text:?}"
72	    );
73	    let hex = &text[..text.len() - 1];
74	    assert_eq!(hex.len(), 64, "digest line must be 64 chars: {text:?}");
75	    assert!(
76	        hex.chars()
77	            .all(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase()),
78	        "digest must be lowercase hex only: {hex:?}"
79	    );
80	    hex
81	}
82	
83	/// 成功路径的完整约定：退出码 0、标准输出只有摘要行、标准错误为空。
84	fn assert_success(output: &Output) -> String {
85	    assert_eq!(output.status.code(), Some(0), "exit code: {output:?}");
86	    assert!(
87	        output.stderr.is_empty(),
88	        "stderr must be empty on success: {:?}",
89	        String::from_utf8_lossy(&output.stderr)
90	    );
91	    assert_hex_stdout(&output.stdout).to_owned()
92	}
93	
94	/// 打开/读取失败的完整约定：退出码 1、标准输出为空、标准错误单行说明。
95	fn assert_failure(output: &Output) -> String {
96	    assert_eq!(output.status.code(), Some(1), "exit code: {output:?}");
97	    assert!(
98	        output.stdout.is_empty(),
99	        "stdout must be empty on failure: {:?}",
100	        String::from_utf8_lossy(&output.stdout)
101	    );
102	    let stderr = String::from_utf8(output.stderr.clone()).expect("stderr must be UTF-8");
103	    assert!(
104	        stderr.ends_with('\n') && !stderr[..stderr.len() - 1].contains('\n'),
105	        "error message must be a single line: {stderr:?}"
106	    );
107	    assert!(
108	        stderr.starts_with("inkseal: cannot "),
109	        "error message must state the failure: {stderr:?}"
110	    );
111	    stderr
112	}
113	
114	/// 与库无关的独立依据：python3 hashlib.sha256(b"abc")。
115	const ABC_HEX: &str = "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad";
116	
117	/// 与库测试相同的独立依据：python3 hashlib.sha256 对 bytes(range(256)) + b"\\x00\\xff\\xfe\\x80"。
118	const BINARY_HEX: &str = "ae1754116b130744d081ccc09988962b3e875ec0e0d6194f2c950e8fe7e27a3d";
119	
120	fn binary_content() -> Vec<u8> {
121	    (0u8..=255).chain([0x00, 0xff, 0xfe, 0x80]).collect()
122	}
123	
124	#[test]
125	fn digest_of_plain_file_matches_content() {
126	    let dir = TestDir::new("plain");
127	    let path = dir.write_file(OsStr::new("hello.txt"), b"abc");
128	
129	    let output = run_digest(path.as_os_str());
130	
131	    let hex = assert_success(&output);
132	    assert_eq!(hex, ABC_HEX);
133	}
134	
135	#[test]
136	fn filename_with_spaces_and_non_ascii_characters_is_read() {
137	    let dir = TestDir::new("unicode-names");
138	    // 空格、中文、其他非 ASCII 字符都应与普通路径一样成功读取。
139	    for name in ["my file.txt", "报告 最终版.txt", "données été.bin"] {
140	        let path = dir.write_file(OsStr::new(name), b"abc");
141	        let output = run_digest(path.as_os_str());
142	        let hex = assert_success(&output);
143	        assert_eq!(hex, ABC_HEX, "digest for file named {name:?}");
144	    }
145	}
146	
147	#[test]
148	fn same_content_in_different_names_and_locations_gives_same_digest() {
149	    let dir = TestDir::new("same-content");
150	    let sub = dir.path().join("nested").join("deeper");
151	    fs::create_dir_all(&sub).unwrap();
152	
153	    // 相同内容放在不同名称、不同位置：摘要必须相同，路径文字不得参与计算。
154	    let first = dir.write_file(OsStr::new("alpha.bin"), b"shared content");
155	    let second = dir.write_file(OsStr::new("完全 不同 的名字.bin"), b"shared content");
156	    let third = sub.join("alpha.bin");
157	    fs::write(&third, b"shared content").unwrap();
158	
159	    let expected = inkseal::digest_reader(&b"shared content"[..])
160	        .unwrap()
161	        .to_hex();
162	    for path in [&first, &second, &third] {
163	        let output = run_digest(path.as_os_str());
164	        let hex = assert_success(&output);
165	        assert_eq!(hex, expected, "digest must not depend on path {path:?}");
166	    }
167	}
168	
169	#[test]
170	fn zero_bytes_and_non_utf8_content_hashed_verbatim() {
171	    let dir = TestDir::new("binary-content");
172	    let path = dir.write_file(OsStr::new("blob.bin"), &binary_content());
173	
174	    let output = run_digest(path.as_os_str());
175	
176	    // 任何文本解码、换行转换或编码规范化都会改变这些字节，从而改变摘要。
177	    let hex = assert_success(&output);
178	    assert_eq!(hex, BINARY_HEX);
179	}
180	
181	#[test]
182	fn success_stdout_is_exactly_64_lowercase_hex_and_newline() {
183	    let dir = TestDir::new("output-shape");
184	    let path = dir.write_file(OsStr::new("f"), b"abc");
185	
186	    let output = run_digest(path.as_os_str());
187	
188	    assert_eq!(output.status.code(), Some(0));
189	    assert!(output.stderr.is_empty());
190	    // 逐字节核对：不多不少，方便把结果直接交给其他工具。
191	    assert_eq!(output.stdout, format!("{ABC_HEX}\n").as_bytes());
