385	/// 匹配的完整约定：退出码 0、标准输出只有 `OK\n`、标准错误为空。
386	fn assert_check_ok(output: &Output) {
387	    assert_eq!(output.status.code(), Some(0), "exit code: {output:?}");
388	    assert_eq!(output.stdout, b"OK\n", "stdout must be exactly OK\\n: {output:?}");
389	    assert!(
390	        output.stderr.is_empty(),
391	        "stderr must be empty on match: {:?}",
392	        String::from_utf8_lossy(&output.stderr)
393	    );
394	}
