1	//! inkseal 的库接口：对任意实现 [`std::io::Read`] 的输入计算 SHA-256 摘要。
2	//!
3	//! 摘要只取决于输入的原始字节，与命令行 `inkseal digest <文件>` 遵循同一内容规则。
4	
5	use sha2::{Digest, Sha256};
6	use std::error::Error;
7	use std::fmt;
8	use std::io::{self, Read};
9	
10	/// SHA-256 摘要结果，可表示为 64 个小写十六进制字符。
11	#[derive(Clone, Copy, PartialEq, Eq, Hash)]
12	pub struct Sha256Digest([u8; 32]);
13	
14	impl Sha256Digest {
15	    /// 返回摘要的原始 32 字节。
16	    pub fn as_bytes(&self) -> &[u8; 32] {
17	        &self.0
18	    }
19	
20	    /// 返回 64 个小写十六进制字符，与命令行输出一致（不含换行）。
21	    pub fn to_hex(&self) -> String {
22	        let mut hex = String::with_capacity(64);
23	        for byte in self.0 {
24	            hex.push(char::from_digit((byte >> 4) as u32, 16).unwrap());
25	            hex.push(char::from_digit((byte & 0x0f) as u32, 16).unwrap());
26	        }
27	        hex
28	    }
29	}
30	
31	impl fmt::Display for Sha256Digest {
32	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
33	        f.write_str(&self.to_hex())
34	    }
35	}
36	
37	impl fmt::Debug for Sha256Digest {
38	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
39	        write!(f, "Sha256Digest({self})")
40	    }
41	}
42	
43	/// 从十六进制文本解析 [`Sha256Digest`] 失败时返回的类型化错误。
44	///
45	/// 两类失败可以按变体区分：长度不符时携带输入的实际 UTF-8 字节长度；
46	/// 长度正确但含非法字符时携带首个非法字节从零开始的字节偏移。
47	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
48	pub enum ParseDigestError {
49	    /// 输入的 UTF-8 字节长度不是 64；携带实际字节长度。
50	    InvalidLength(usize),
51	    /// 长度为 64 但含有非十六进制字符；携带首个非法字节的字节偏移
52	    /// （按原始文本的字节计算，不按字符个数）。
53	    InvalidHexChar(usize),
54	}
55	
56	impl ParseDigestError {
57	    /// 长度不符时返回输入的实际字节长度，否则返回 `None`。
58	    pub fn actual_length(&self) -> Option<usize> {
59	        match self {
60	            ParseDigestError::InvalidLength(len) => Some(*len),
61	            ParseDigestError::InvalidHexChar(_) => None,
62	        }
63	    }
64	
65	    /// 含非法字符时返回首个非法字节的字节偏移，否则返回 `None`。
66	    pub fn invalid_position(&self) -> Option<usize> {
67	        match self {
68	            ParseDigestError::InvalidLength(_) => None,
69	            ParseDigestError::InvalidHexChar(pos) => Some(*pos),
70	        }
71	    }
72	}
73	
74	impl fmt::Display for ParseDigestError {
75	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
76	        match self {
77	            ParseDigestError::InvalidLength(len) => write!(
78	                f,
79	                "digest must be exactly 64 ASCII hexadecimal characters, got {len} bytes"
80	            ),
81	            ParseDigestError::InvalidHexChar(pos) => {
82	                write!(f, "digest contains a non-hexadecimal byte at offset {pos}")
83	            }
84	        }
85	    }
86	}
87	
88	impl Error for ParseDigestError {}
89	
90	fn hex_nibble(b: u8) -> Option<u8> {
91	    match b {
92	        b'0'..=b'9' => Some(b - b'0'),
93	        b'a'..=b'f' => Some(b - b'a' + 10),
94	        b'A'..=b'F' => Some(b - b'A' + 10),
95	        _ => None,
96	    }
97	}
98	
99	impl std::str::FromStr for Sha256Digest {
100	    type Err = ParseDigestError;
101	
102	    /// 从 64 个 ASCII 十六进制字符解析摘要。
103	    ///
104	    /// 接受 `0-9`、`a-f` 和 `A-F`，大小写混用表示同一个摘要。输入必须
105	    /// 恰好是 64 个字符：不做任何裁剪或修正，空白、末尾换行、`0x` 前缀、
106	    /// 分隔符以及全角数字等非 ASCII 内容都属于格式错误。长度按输入的
107	    /// UTF-8 字节数判断，非法字符的位置也按字节偏移报告。
108	    fn from_str(s: &str) -> Result<Self, Self::Err> {
109	        let bytes = s.as_bytes();
110	        if bytes.len() != 64 {
111	            return Err(ParseDigestError::InvalidLength(bytes.len()));
112	        }
113	        let mut out = [0u8; 32];
114	        for (i, pair) in bytes.chunks_exact(2).enumerate() {
115	            let hi = hex_nibble(pair[0])
116	                .ok_or(ParseDigestError::InvalidHexChar(2 * i))?;
117	            let lo = hex_nibble(pair[1])
118	                .ok_or(ParseDigestError::InvalidHexChar(2 * i + 1))?;
119	            out[i] = (hi << 4) | lo;
120	        }
121	        Ok(Sha256Digest(out))
122	    }
123	}
124	
125	/// 计算摘要过程中读取输入失败时返回的类型化错误。
126	#[derive(Debug)]
127	pub struct DigestError(io::Error);
128	
129	impl DigestError {
130	    /// 取出底层的 I/O 错误。
131	    pub fn into_inner(self) -> io::Error {
132	        self.0
133	    }
134	}
135	
136	impl fmt::Display for DigestError {
137	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
138	        write!(f, "failed to read input: {}", self.0)
139	    }
140	}
141	
142	impl Error for DigestError {
143	    fn source(&self) -> Option<&(dyn Error + 'static)> {
144	        Some(&self.0)
145	    }
146	}
147	
148	impl From<io::Error> for DigestError {
149	    fn from(err: io::Error) -> Self {
150	        DigestError(err)
151	    }
152	}
153	
154	/// 以流式方式读取 `reader` 的全部字节并计算 SHA-256 摘要。
155	///
156	/// 内存占用与输入大小无关。读取失败时返回 [`DigestError`]，绝不返回部分内容的摘要。
157	///
158	/// [`io::ErrorKind::Interrupted`] 是临时中断而非输入结束：本次读取没有
159	/// 消费任何字节，直接重试同一位置，摘要与未发生中断时完全一致。其他
160	/// 错误（权限不足、数据损坏等）仍然立即失败。
161	pub fn digest_reader<R: Read>(mut reader: R) -> Result<Sha256Digest, DigestError> {
162	    let mut hasher = Sha256::new();
163	    let mut buf = [0u8; 64 * 1024];
164	    loop {
165	        match reader.read(&mut buf) {
166	            Ok(0) => break,
167	            Ok(n) => hasher.update(&buf[..n]),
168	            Err(ref err) if err.kind() == io::ErrorKind::Interrupted => continue,
169	            Err(err) => return Err(DigestError(err)),
170	        }
171	    }
172	    Ok(Sha256Digest(hasher.finalize().into()))
173	}
