308	    /// 用于精确模拟“中断出现在任意位置”的读取序列。
309	    enum Step {
310	        /// 返回下一段内容（可为空切片以外的任意长度）。
311	        Data,
312	        /// 返回指定错误。
313	        Fail(io::ErrorKind, &'static str),
