335	                    // 且片段长度通常短于缓冲区容量。
336	                    let remaining = self.data.len() - self.pos;
337	                    let n = (remaining / 2).max(1).min(remaining).min(buf.len());
338	                    buf[..n].copy_from_slice(&self.data[self.pos..self.pos + n]);
339	                    self.pos += n;
