346	                None => {
347	                    let remaining = self.data.len() - self.pos;
348	                    let n = remaining.min(buf.len());
349	                    buf[..n].copy_from_slice(&self.data[self.pos..self.pos + n]);
350	                    self.pos += n;
351	                    Ok(n)
