476	        assert!(err.to_string().contains("corrupt sector 7"));
477	        let source = std::error::Error::source(&err).expect("typed error keeps its cause");
478	        assert!(source.to_string().contains("corrupt sector 7"));
479	    }
480	
481	    #[test]
482	    fn digest_representations_express_the_same_value() {
483	        let digest = digest_reader(&b"abc"[..]).unwrap();
484	        let hex = digest.to_hex();
485	
486	        // 原始字节与十六进制文本表达同一个值。
487	        let mut from_bytes = String::with_capacity(64);
488	        for byte in digest.as_bytes() {
489	            use std::fmt::Write as _;
490	            let _ = write!(from_bytes, "{byte:02x}");
491	        }
492	        assert_eq!(from_bytes, hex);
493	
494	        // Display 与 to_hex 一致。
495	        assert_eq!(format!("{digest}"), hex);
496	
497	        // 恰好 64 个小写十六进制字符，无文件名、标签、空白或换行。
498	        assert_eq!(hex.len(), 64);
499	        assert!(hex.chars().all(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase()));
500	        assert!(!hex.chars().any(char::is_whitespace));
501	    }
502	
503	    #[test]
504	    fn digest_parses_back_from_its_own_hex() {
505	        use std::str::FromStr;
506	        let digest = digest_reader(&b"abc"[..]).unwrap();
507	
508	        // 标准字符串解析方式：str::parse 与 FromStr::from_str 等价。
509	        let parsed: Sha256Digest = digest.to_hex().parse().unwrap();
510	        assert_eq!(parsed, digest);
511	        assert_eq!(Sha256Digest::from_str(&digest.to_hex()).unwrap(), digest);
512	
513	        // 解析结果的 32 字节与文本表示的值逐字节一致，
514	        // 既有字节访问与显示功能直接可用。
515	        assert_eq!(parsed.as_bytes(), digest.as_bytes());
516	        assert_eq!(parsed.to_hex(), digest.to_hex());
517	        assert_eq!(format!("{parsed}"), digest.to_hex());
518	    }
519	
520	    #[test]
521	    fn parsing_accepts_mixed_case_and_preserves_leading_zeros() {
522	        use std::str::FromStr;
523	        // 含前导零与大小写混用的已知摘要（SHA-256 of "The quick brown fox...")。
524	        let lower = "d7a8fbb307d7809469ca9abcb0082e4f8d5651e46d3cdb762d02d0bf37c9e592";
525	        let mixed = "D7a8FbB307d7809469CA9abCB0082E4f8D5651E46D3Cdb762D02d0BF37C9E592";
526	        let from_lower = Sha256Digest::from_str(lower).unwrap();
527	        let from_mixed: Sha256Digest = mixed.parse().unwrap();
528	
529	        // 大小写混用表示同一个摘要。
530	        assert_eq!(from_lower, from_mixed);
531	
532	        // 前导零保留在字节值中，输出仍是 64 个小写十六进制字符。
533	        let with_zero: Sha256Digest =
534	            "00b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
535	                .parse()
536	                .unwrap();
537	        assert_eq!(with_zero.as_bytes()[0], 0x00);
538	        assert_eq!(
539	            with_zero.to_hex(),
540	            "00b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
541	        );
542	    }
543	
544	    #[test]
545	    fn parse_rejects_wrong_length_and_reports_actual_length() {
546	        use std::str::FromStr;
547	        // 空字符串不能变成空文件的摘要。
548	        let err = Sha256Digest::from_str("").unwrap_err();
549	        assert_eq!(err, ParseDigestError::InvalidLength(0));
550	        assert_eq!(err.actual_length(), Some(0));
551	        assert_eq!(err.invalid_position(), None);
552	
553	        // 63 与 65 个字符都不接受。
554	        assert_eq!(
555	            Sha256Digest::from_str(
556	                "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b85"
557	            )
558	            .unwrap_err(),
559	            ParseDigestError::InvalidLength(63)
560	        );
561	        assert_eq!(
562	            Sha256Digest::from_str(
563	                "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b8550"
564	            )
565	            .unwrap_err(),
566	            ParseDigestError::InvalidLength(65)
567	        );
568	
569	        // 长度按 UTF-8 字节数判断：全角数字一个字符占 3 字节。
570	        let fullwidth = "０".repeat(21); // 21 个字符，63 字节
571	        let err = Sha256Digest::from_str(&fullwidth).unwrap_err();
572	        assert_eq!(err, ParseDigestError::InvalidLength(63));
573	        assert_eq!(err.actual_length(), Some(63));
574	    }
575	
576	    #[test]
577	    fn parse_rejects_non_hex_bytes_and_reports_first_byte_offset() {
578	        use std::str::FromStr;
579	        // 非法字符出现在偶数与奇数位置，位置从零开始按字节计。
580	        let err = Sha256Digest::from_str(
581	            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b85g",
582	        )
583	        .unwrap_err();
584	        assert_eq!(err, ParseDigestError::InvalidHexChar(63));
585	        assert_eq!(err.invalid_position(), Some(63));
586	        assert_eq!(err.actual_length(), None);
587	
588	        let err = Sha256Digest::from_str(
589	            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b8z5",
590	        )
591	        .unwrap_err();
592	        assert_eq!(err, ParseDigestError::InvalidHexChar(62));
593	
594	        // 报告的是首个非法字节：后面的非法字符不影响位置。
595	        let err = Sha256Digest::from_str(
596	            "zzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzz",
597	        )
598	        .unwrap_err();
599	        assert_eq!(err, ParseDigestError::InvalidHexChar(0));
600	
601	        // 全角数字等非 ASCII 内容不作为十六进制字符接受；
602	        // 位置按原始文本的字节偏移报告，不按字符个数。
603	        // "e3" + "３"（3 字节）+ 59 个 '0'，共 64 字节，非法字节从偏移 2 开始。
604	        let s = format!("e3３{}", "0".repeat(59));
605	        assert_eq!(s.len(), 64);
606	        let err = Sha256Digest::from_str(&s).unwrap_err();
607	        assert_eq!(err, ParseDigestError::InvalidHexChar(2));
608	    }
609	
610	    #[test]
611	    fn parse_does_not_trim_or_fix_input() {
612	        use std::str::FromStr;
613	        let valid = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";
614	
615	        // 末尾换行、首尾空白、0x 前缀、分隔符都是格式错误（长度不符）。
616	        for bad in [
617	            format!("{valid}\n"),
618	            format!(" {valid}"),
619	            format!("{valid} "),
620	            format!("0x{valid}"),
621	            format!("{valid}\r\n"),
622	        ] {
623	            assert!(matches!(
624	                Sha256Digest::from_str(&bad),
625	                Err(ParseDigestError::InvalidLength(_))
626	            ));
627	        }
628	
629	        // 长度恰好 64 但含分隔符：按非法字符处理。
630	        let with_dash = format!("{}-{}", &valid[..31], &valid[32..]);
631	        assert_eq!(with_dash.len(), 64);
632	        assert_eq!(
633	            Sha256Digest::from_str(&with_dash).unwrap_err(),
634	            ParseDigestError::InvalidHexChar(31)
635	        );
636	    }
637	
638	    #[test]
639	    fn parse_error_supports_display_and_error_trait() {
640	        use std::str::FromStr;
641	        let len_err = Sha256Digest::from_str("abc").unwrap_err();
642	        let msg = len_err.to_string();
643	        assert!(msg.contains('3'), "unexpected message: {msg}");
644	        assert!(msg.contains("64"), "unexpected message: {msg}");
645	
646	        let char_err = Sha256Digest::from_str(
647	            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b85g",
648	        )
649	        .unwrap_err();
650	        assert!(char_err.to_string().contains("63"));
651	
652	        // 两类错误可按类型区分，且都实现 std::error::Error，可常规传递。
653	        fn assert_error<T: std::error::Error>(_: &T) {}
654	        assert_error(&len_err);
655	        assert_error(&char_err);
656	        assert_ne!(len_err, char_err);
657	        let boxed: Box<dyn std::error::Error> = Box::new(char_err);
658	        assert!(boxed.to_string().contains("63"));
659	    }
660	}
